/// `List<T>.Remove(item)`: removes the first equal element, returns whether it found one.
fn list_remove<T: PartialEq>(list: &mut Vec<T>, item: &T) -> bool {
    match list.iter().position(|x| x == item) {
        Some(i) => {
            list.remove(i);
            true
        }
        None => false,
    }
}

